const ExcelJS = require('exceljs');
async function checkAssigned() {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile('data/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx');
  const ws = wb.getWorksheet('기업 정보');
  let bhmCount = 0;
  let minRow = Infinity;
  let maxRow = -1;
  ws.eachRow((r, rowNumber) => {
    const val = r.getCell(1).value;
    if (val && val.toString().includes('배현명')) {
      bhmCount++;
      if (rowNumber < minRow) minRow = rowNumber;
      if (rowNumber > maxRow) maxRow = rowNumber;
    }
  });
  console.log('Total rows for 배현명 in Col 1:', bhmCount, 'from row', minRow, 'to', maxRow);
}
checkAssigned();
